text:
{
  "outline": [
    {
      "title": "极限：微积分的地基",
      "summary": "学习数列极限的ε-N定义、函数极限的ε-δ定义，以及两个重要极限，这是后续所有概念的基础。",
      "kc_names": ["极限"]
    },
    {
      "title": "无穷小与函数连续性",
      "summary": "掌握无穷小量的比较、等价无穷小替换，以及函数连续的定义、间断点分类和闭区间上连续函数的性质。",
      "kc_names": ["无穷小量", "等价无穷小", "函数的连续性"]
    },
    {
      "title": "导数与微分计算",
      "summary": "理解导数的定义和几何意义，熟记基本初等函数导数表，掌握四则、复合、反函数求导法则及高阶导数、隐函数求导。",
      "kc_names": ["导数", "基本初等函数导数表", "求导法则", "高阶导数", "隐函数求导"]
    },
    {
      "title": "微分中值定理与洛必达法则",
      "summary": "学习罗尔、拉格朗日、柯西中值定理，以及洛必达法则，它们是导数应用和极限计算的核心工具。",
      "kc_names": ["罗尔定理", "拉格朗日中值定理", "柯西中值定理", "洛必达法则"]
    },
    {
      "title": "泰勒公式：逼近与展开",
      "summary": "掌握泰勒多项式和余项形式，熟记常用函数的麦克劳林展开，并学会用泰勒公式进行近似计算和求极限。",
      "kc_names": ["泰勒公式", "麦克劳林展开"]
    },
    {
      "title": "积分：从不定积分到定积分应用",
      "summary": "理解不定积分与基本积分表，掌握换元积分法和分部积分法，学习定积分的定义、牛顿-莱布尼茨公式及其在面积、体积等中的应用。",
      "kc_names": ["不定积分", "换元积分法", "分部积分法", "定积分", "牛顿-莱布尼茨公式", "定积分的应用"]
    }
  ],
  "glossary": [
    {"term": "极限", "definition": "当自变量无限趋近某值时，函数值无限趋近于一个确定的常数，这个常数就是极限。"},
    {"term": "无穷小量", "definition": "极限为0的变量，是微积分中用于比较和替换的基本工具。"},
    {"term": "等价无穷小", "definition": "两个无穷小量之比极限为1，可在乘除运算中互相替换以简化计算。"},
    {"term": "导数", "definition": "函数在某点的瞬时变化率，几何上表示切线的斜率。"},
    {"term": "微分中值定理", "definition": "在满足一定条件的区间内，存在一点使得导数等于区间平均变化率，是连接函数与导数的桥梁。"},
    {"term": "泰勒公式", "definition": "用多项式逼近光滑函数的方法，余项表示逼近的误差。"},
    {"term": "不定积分", "definition": "导数的逆运算，求一个函数的所有原函数，结果包含一个任意常数。"},
    {"term": "定积分", "definition": "函数在区间上的累积和，几何上表示曲线与x轴围成的面积。"}
  ],
  "suggested_questions": [
    "用ε-N定义证明数列$1/n$的极限为0的步骤是什么？",
    "等价无穷小替换在加减运算中为什么不能直接使用？",
    "如何判断一个函数在某点是否可导？举例说明。",
    "拉格朗日中值定理的几何意义是什么？",
    "如何用泰勒公式求极限$\\lim_{x\\to 0}\\frac{\\sin x - x}{x^3}$？",
    "换元积分法和分部积分法分别适用于什么类型的积分？"
  ]
}
